"""Portable HTML export with escaped evidence and no scripts or external assets."""
from html import escape

def render(job):
    esc=lambda value:escape(str(value),quote=True)
    stages=''.join('<tr><td>'+esc(s['name'])+'</td><td>'+esc(s['status'])+'</td><td>'+esc(s.get('detail',''))+'</td></tr>' for s in job.get('stages',[]))
    findings=''.join('<article><h2>'+esc(f['title'])+'</h2><p>'+esc(f['tool'])+' · '+esc(f['severity'])+'</p><p>'+esc(f['url'])+'</p><pre>'+esc(f['evidence'])+'</pre><p>'+esc(f.get('recommendation',''))+'</p></article>' for f in job.get('findings',[]))
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pentest Lab Report</title><style>body{font:15px/1.7 Arial,sans-serif;max-width:960px;margin:50px auto;padding:0 24px;color:#25324b}h1,h2{font-weight:500}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #dde4ed;padding:12px}article{border:1px solid #dde4ed;padding:20px;margin:24px 0;border-radius:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7fb;padding:16px}p{overflow-wrap:anywhere}</style><h1>Pentest Lab Scan Report</h1>'''+f'<p><b>Version</b> {esc(job.get("version","Earlier version"))}<br><b>Target</b> {esc(job.get("target",""))}<br><b>Status</b> {esc(job["status"])}<br><b>Started</b> {esc(job["created"])}</p><p>Automated results require manual validation. Missing or incomplete checks do not establish that the target is secure.</p><h2>Coverage</h2><p>Selected tools: {esc(", ".join(job.get("tools",[])))}</p><table><tr><th>Tool</th><th>Status</th><th>Detail</th></tr>{stages}</table><h2>Findings and observations</h2><p>{len(job.get("findings",[]))} results recorded.</p>{findings}</html>'
